import {
  FocusEvent,
  FocusEventHandler,
  useCallback,
  useEffect,
  useState,
} from 'react';

import { focusRingCSS, focusRingFocusWithinCSS } from './focusRing.sty.js';
import { _useFocusContext } from '../hooks/useFocusContext.js';

export type Modality = 'keyboard' | 'pointer' | 'touch' | 'unknown';

export const variants = [
  'neutral',
  'primary',
  'success',
  'warning',
  'critical',
  'onAccent',
] as const;
export type VariantType = (typeof variants)[number];

export type UseFocusRingProps = {
  /**
   * A minimal focus outline is available for smaller content elements like links. This variant is applied when set to true.
   * @defaultValue false
   */
  isMinimal?: boolean;

  /**
   * Whether or not the modality should be ignored, so that the focus ring is also present if users clicks the element (not just by tabbing to it).
   * @defaultValue false
   */
  ignoreModality?: boolean;

  /**
   * The styling variant of the element.
   * @defaultValue neutral
   */
  variant?: VariantType;

  /**
   * Apply the focus ring styling if an embedded element gains the focus
   */
  focusWithin?: boolean;

  /**
   * Whether the element is disabled. If disabled changes to true, the focus will be removed.
   */
  disabled?: boolean;
};

export type FocusRingProps = {
  /** The focus styles that depend on modality. */
  focusClassName: string;
  /** Focus handlers used to manage the focus state. Must be applied to the element that receives the focus.*/
  focusProps: {
    onFocus: (e: FocusEvent) => void;
    onBlur: (e: FocusEvent) => void;
  };
  /** Whether or not the element got focus via keyboard. */
  isFocusVisible: boolean;
};

/**
 * Custom hook used to determine focus styling depending on modality.
 * Returns the css classes (vanilla) that can be applied to the component in order to show the correct focus outline.
 * @internal
 */
export function useFocusRing(props: UseFocusRingProps = {}): FocusRingProps {
  const {
    variant = 'neutral',
    ignoreModality = false,
    isMinimal = false,
    focusWithin = false,
    disabled = false,
  } = props;
  const [isFocused, setIsFocused] = useState(false);
  const { modality } = _useFocusContext();

  useEffect(() => {
    if (disabled) {
      setIsFocused(false);
    }
  }, [disabled]);

  const onBlur = useCallback<FocusEventHandler>((e) => {
    // trigger only when the self element is unfocused (stopPropagation)
    if (e.currentTarget === e.target) {
      setIsFocused(false);
    }
  }, []);

  const onFocus = useCallback<FocusEventHandler>((e) => {
    // trigger only when the self element is focused (stopPropagation)
    if (e.currentTarget === e.target) {
      setIsFocused(true);
    }
  }, []);

  const focusProps = {
    onFocus,
    onBlur,
  };

  if (
    ((ignoreModality || modality === 'keyboard') && isFocused) ||
    focusWithin
  ) {
    if (isMinimal) {
      return {
        focusClassName: focusWithin
          ? focusRingFocusWithinCSS({ minimal: true, variant })
          : focusRingCSS({ minimal: true, variant }),
        isFocusVisible: !focusWithin,
        focusProps,
      };
    }

    return {
      focusClassName: focusWithin
        ? focusRingFocusWithinCSS({ minimal: false, variant })
        : focusRingCSS({ minimal: false, variant }),
      isFocusVisible: !focusWithin,
      focusProps,
    };
  }

  return {
    focusClassName: focusWithin ? focusRingFocusWithinCSS() : focusRingCSS(),
    isFocusVisible: false,
    focusProps,
  };
}
